function km(a,b,c,d){let x=(c-a)*Math.PI/180,y=(d-b)*Math.PI/180,z=Math.sin(x/2)**2+Math.cos(a*Math.PI/180)*Math.cos(c*Math.PI/180)*Math.sin(y/2)**2;return 6371*2*Math.atan2(Math.sqrt(z),Math.sqrt(1-z))}function Map({malls,origin,onSelect}){const el=useRef(),map=useRef();useEffect(()=>{if(!el.current)return;map.current=L.map(el.current,{scrollWheelZoom:false}).setView([1.3521,103.8198],11);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:19}).addTo(map.current);return()=>{map.current?.remove();map.current=null}},[]);useEffect(()=>{if(!map.current)return;const layer=L.layerGroup().addTo(map.current),pts=[];malls.forEach(m=>{const marker=L.circleMarker([m.lat,m.lon],{radius:9,color:'#fff',weight:2,fillColor:'#1d847e',fillOpacity:1}).addTo(layer).bindTooltip(m.name);marker.on('click',()=>onSelect(m));pts.push([m.lat,m.lon])});if(origin){L.circleMarker([origin.lat,origin.lon],{radius:9,color:'#fff',weight:3,fillColor:'#e58d47',fillOpacity:1}).addTo(layer).bindTooltip('Your starting location');pts.push([origin.lat,origin.lon])}if(pts.length)map.current.fitBounds(pts,{padding:[35,35],maxZoom:13});return()=>layer.remove()},[malls,origin,onSelect]);return <div className="map" ref={el}/>}
import MALL_PHOTOS from './mall-photos.json';
function MallPhoto({name}){
 const [failed,setFailed]=useState(false);
 const photo=MALL_PHOTOS[name];
 return photo&&!failed?<figure className="mallphoto mallphoto-real"><img src={photo.src} alt={`${name} shopping mall exterior`} loading="lazy" decoding="async" onError={()=>setFailed(true)}/>{photo.credit&&<figcaption>Photo: <a href={photo.page} target="_blank" rel="noopener noreferrer">{photo.credit}</a> · <a href={photo.licenseUrl} target="_blank" rel="noopener noreferrer">{photo.license}</a>{photo.modified?' · Cropped for display':''}</figcaption>}</figure>:<div className="mallphoto mallphoto-fallback" role="img" aria-label={`${name} exterior photo unavailable`}><Store size={25}/><span>{name}</span><small>Exterior photograph unavailable</small></div>
}
// Consistent quality rules applied to every mall and every outlet.
const outlet=(mall,brand)=>STORE_FACTS[mall+'|'+brand]||{};
const outletStatus=(mall,brand)=>{const d=outlet(mall,brand);return d.verification==='verified_unit'?'Verified unit':d.source&&d.unit?'Legacy sourced — recheck':d.source?'Location claimed — recheck':'Needs verification'};
const sgMinutes=()=>{const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Singapore',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(new Date());return Number(parts.find(x=>x.type==='hour').value)*60+Number(parts.find(x=>x.type==='minute').value)};
function storeOpenStatus(hours){if(!hours)return 'Hours unavailable';if(/24 hours/i.test(hours))return 'Open 24 hours';const x=hours.match(/(?:Daily\s*)?(\d{1,2})(?::(\d{2}))?\s*(am|pm)\s*[–-]\s*(\d{1,2})(?::(\d{2}))?\s*(am|pm)/i);if(!x||!/^Daily/i.test(hours))return 'Check day-specific hours';const cv=(h,m,amp)=>((Number(h)%12)+(amp.toLowerCase()==='pm'?12:0))*60+Number(m||0);const start=cv(x[1],x[2],x[3]),end=cv(x[4],x[5],x[6]),now=sgMinutes();return end>start?(now>=start&&now<end?'Likely open now':'Likely closed now'):(now>=start||now<end?'Likely open now':'Likely closed now')}
