function activityCompletions(input,lang){
 const choices=ACTIVITY_COMPLETIONS[lang]||ACTIVITY_COMPLETIONS.en;
 const q=input.toLocaleLowerCase().trim();
 if(!q)return choices.slice(0,10);
 const words=q.split(/[\s,，。.!?、]+/).filter(w=>w.length>1);
 const ranked=choices.map((value,index)=>{
   const lower=value.toLocaleLowerCase();
   const intent=interpretActivity(value,lang);
   const aliasScore=COMPLETION_ALIASES.reduce((score,aliases)=>score+(aliases.some(x=>q.includes(x))&&aliases.some(x=>lower.includes(x))?4:0),0);
   const score=(lower.startsWith(q)?20:0)+(lower.includes(q)?12:0)+words.filter(w=>lower.includes(w)).length*3+aliasScore+(intent.some(x=>x.terms.some(t=>q.includes(t)))?4:0);
   return {value,score,index};
 }).sort((a,b)=>b.score-a.score||a.index-b.index);
 return ranked.filter(x=>x.score>0).slice(0,8).map(x=>x.value).concat(ranked.filter(x=>x.score===0).slice(0,4).map(x=>x.value)).slice(0,10);
}
function interpretActivity(input,lang){const q=input.toLocaleLowerCase().trim();if(!q)return [];return ACTIVITY_INTENTS.filter(a=>a.id==='specialdining'?isSpecialDining(q):a.terms.some(term=>q.includes(term.toLocaleLowerCase()))).map(a=>({...a,label:a.labels[lang]}));}
function activityMatch(m,intents){return intents.map(a=>({...a,found:a.brands.filter(b=>m.shops.includes(b))}));}
