function singaporeDay(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Singapore',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=k=>Number(parts.find(p=>p.type===k)?.value);return {year:get('year'),month:get('month'),day:get('day')}}
function currentOccasions(){const now=singaporeDay();const today=Date.UTC(now.year,now.month-1,now.day);return OCCASIONS.filter(o=>!o.year||o.year===now.year).map(o=>({...o,daysAway:Math.round((Date.UTC(o.year||now.year,o.month-1,o.day)-today)/86400000)})).filter(o=>o.daysAway>=0&&o.daysAway<=2).sort((a,b)=>a.daysAway-b.daysAway)}
