function estimatedPrice(brand){
 if(PRICE_EXPLICIT[brand])return PRICE_EXPLICIT[brand];
 const cats=Object.entries(ALL_CATEGORIES).filter(([k,v])=>FOOD_HINTS.test(k)&&v.includes(brand)).map(([k])=>k);
 if(!cats.length)return null;
 const c=cats.join(' ').toLowerCase();
 if(/fast food|hawker|local food/.test(c))return 1;
 if(/cafe|coffee|beverage|dessert|bakery/.test(c))return 2;
 return 3;
}
